/* every venue with a DeFiLlama slug keeps its daily series here, keyed by name.
   refreshLlama already downloads most of them for the 30D figures, so widening
   the browser to more venues costs no extra requests. */
const DAILY={};
VENUES.forEach(v=>{ DAILY[v.n]={}; });
(function seedVariational(){
  const cum={}; VAR_TREASURY_CUM.split(',').forEach(p=>{const [d,v]=p.split(':'); cum['2026-'+d]=+v;});
  const days=Object.keys(cum).sort();
  const fee={},rev={},sup={};
  days.forEach((d,i)=>{ if(!i) return;
    const inflow=Math.max(cum[d]-cum[days[i-1]],0);
    rev[d]=inflow; fee[d]=inflow/VAR_SPREAD_SHARE; sup[d]=fee[d]-inflow;
  });
  Object.assign(DAILY['Variational'],{fee,rev,sup});
})();

/* which venues can appear in the browser: Variational is fixed, the rest are opt-in */
