let ML_SEL='fee', ML_RANGE='8W';

function windowBuckets(mode){
  if(mode==='30D') return Array.from({length:30},(_,i)=>({end:addDaysIso(ANCHOR,-(29-i)),days:1}));
  const n=mode==='26W'?26:mode==='90D'?13:8;
  return Array.from({length:n},(_,i)=>({end:addDaysIso(ANCHOR,-7*(n-1-i)),days:7}));
}
function addDaysIso(iso,n){
  const d=new Date(iso+'T00:00:00Z'); d.setUTCDate(d.getUTCDate()+n);
  return d.toISOString().slice(0,10);
}
const bucketSum=(m,b)=>{
  let tot=0,hit=0;
  for(let i=0;i<b.days;i++){ const d=addDaysIso(b.end,-i); if(m&&m[d]!=null){tot+=m[d];hit++;} }
  return hit>=Math.max(1,Math.ceil(b.days*0.7))?tot:null;
};
const bucketLast=(m,b)=>{
  for(let i=0;i<b.days;i++){ const d=addDaysIso(b.end,-i); if(m&&m[d]!=null) return m[d]; }
  return null;
};
const WEEK_FALLBACK={Variational:'VAR',Lighter:'LTR',Extended:'EXT'};

/* raw series for one venue+key over the window; falls back to the baked weekly
   snapshot for the original three when the daily feed has not arrived */
function baseSeries(name,key,mode,buckets){
  const daily=DAILY[name]&&DAILY[name][key];
  const pick=key==='oi'?bucketLast:bucketSum;
  if(daily&&Object.keys(daily).length){
    const out=buckets.map(b=>pick(daily,b));
    if(out.some(v=>v!=null)) return out;
  }
  const tag=WEEK_FALLBACK[name];
  if(mode==='8W'&&tag&&WEEKLY[tag]&&WEEKLY[tag][key]) return WEEKLY[tag][key].slice();
  return buckets.map(()=>null);
}
/* field totals for the share metrics: every venue that reports the series */
function fieldTotals(key,mode,buckets){
  const tot=buckets.map(()=>0);
  VENUES.forEach(v=>{
    const s=baseSeries(v.n,key,mode,buckets);
    s.forEach((x,i)=>{ if(x!=null) tot[i]+=x; });
  });
  return tot;
}
function mlSeries(name,k,mode,buckets){
  const div=(a,b,mult)=>a.map((x,i)=>(x!=null&&b[i])?x/b[i]*mult:null);
  if(k==='take')     return div(baseSeries(name,'fee',mode,buckets),baseSeries(name,'vol',mode,buckets),1e4);
  if(k==='cap')      return div(baseSeries(name,'rev',mode,buckets),baseSeries(name,'fee',mode,buckets),100);
  if(k==='feeOnOi')  return div(baseSeries(name,'fee',mode,buckets),baseSeries(name,'oi',mode,buckets),100);
  if(k==='turn')     return div(baseSeries(name,'vol',mode,buckets),baseSeries(name,'oi',mode,buckets),1);
  /* until every venue's OI history is in, the denominator would only be the venues
     already loaded — that reads as a much larger share than reality */
  if(k==='oiShare')  return FIELD_OI_READY
    ? div(baseSeries(name,'oi',mode,buckets),fieldTotals('oi',mode,buckets),100)
    : buckets.map(()=>null);
  if(k==='volShare') return div(baseSeries(name,'vol',mode,buckets),fieldTotals('vol',mode,buckets),100);
  return baseSeries(name,k,mode,buckets);
}
const lastOf=a=>{for(let i=a.length-1;i>=0;i--) if(a[i]!=null) return {v:a[i],i}; return null;};
const mlPicked=()=>ML_PICK.map(n=>ML_ALL.find(x=>x.n===n)).filter(Boolean)
  .map((v,i)=>({...v,cls:ML_COLOR[i]||'v-d'}));

function renderVenuePicker(){
  const host=$('#mlVenues'); if(!host) return;
  host.innerHTML=`<span class="ml-vlabel">Venues</span>`+ML_ALL.map(v=>{
    const on=ML_PICK.includes(v.n);
    const full=!on&&ML_PICK.length>=ML_MAX;
    const idx=ML_PICK.indexOf(v.n);
    return `<button type="button" class="ml-chip${on?' on '+(ML_COLOR[idx]||'v-d'):''}"
      data-venue="${esc(v.n)}"${v.fixed||full?' disabled':''}
      title="${v.fixed?'always shown':full?'four series maximum — drop one first':esc(v.n)}">${v.short}</button>`;
  }).join('')+`<span class="ml-vhint">up to ${ML_MAX}</span>`;
  host.querySelectorAll('.ml-chip').forEach(b=>b.addEventListener('click',()=>{
    const n=b.dataset.venue;
    if(ML_PICK.includes(n)) ML_PICK=ML_PICK.filter(x=>x!==n);
    else if(ML_PICK.length<ML_MAX) ML_PICK=[...ML_PICK,n];
    renderMetricLab(); ensureSeries();
  }));
}

function renderMetricList(){
  const host=$('#mlRows'); if(!host) return;
  const buckets=windowBuckets(ML_RANGE);
  const picked=mlPicked();
  const head=$('#mlHead');
  if(head) head.innerHTML=`<th>Metric</th>`+picked.map(v=>{
    const ven=byName(v.n);
    return `<th class="num"><img src="${ven?ven.logo:''}" alt="" width="15" height="15">${v.short}</th>`;
  }).join('');
  let group='';
  host.innerHTML=METRICS.map(m=>{
    let lead='';
    if(m.group!==group){ group=m.group;
      lead=`<tr class="ml-group"><td colspan="${picked.length+1}">${GROUPS[group]}</td></tr>`; }
    const cells=picked.map(v=>{
      const ser=mlSeries(v.n,m.k,ML_RANGE,buckets), last=lastOf(ser);
      if(!last) return `<td class="num na"><b>—</b><span>no series</span></td>`;
      const prev=last.i>0?ser[last.i-1]:null;
      const dv=(prev!=null&&prev!==0)?(last.v-prev)/Math.abs(prev)*100:null;
      const arrow=dv==null?'':(dv>=0?'▲':'▼')+Math.abs(dv).toFixed(0)+'%';
      return `<td class="num ${v.cls==='v-me'?'me':''}"><b>${m.fmt(last.v)}</b>`
        +`<span class="${dv==null?'':dv>=0?'up':'down'}">${arrow||' '}</span></td>`;
    }).join('');
    return lead+`<tr class="ml-row${m.k===ML_SEL?' on':''}" data-metric="${m.k}" tabindex="0" role="button"
      aria-pressed="${m.k===ML_SEL}"><td class="metric"><b>${m.label}</b><span>${m.kind==='stock'?'level'
      :m.kind==='flow'?'per period':'ratio'}</span></td>${cells}</tr>`;
  }).join('');
  host.querySelectorAll('.ml-row').forEach(r=>{
    const pick=()=>{ ML_SEL=r.dataset.metric; renderMetricLab(); };
    r.addEventListener('click',pick);
    r.addEventListener('keydown',e=>{ if(e.key==='Enter'||e.key===' '){e.preventDefault();pick();} });
  });
}

function renderRangeButtons(){
  const host=$('#mlRange'); if(!host) return;
  const liveDaily=Object.values(DAILY).some(d=>d.vol&&Object.keys(d.vol).length);
  host.innerHTML=['30D','8W','90D','26W'].map(r=>{
    const off=r!=='8W'&&!liveDaily;
    return `<button type="button" class="rg${r===ML_RANGE?' on':''}" data-range="${r}"${off?' disabled':''}
      title="${off?'daily series still loading':''}">${r}</button>`;
  }).join('');
  host.querySelectorAll('.rg').forEach(b=>b.addEventListener('click',()=>{
    ML_RANGE=b.dataset.range; renderMetricLab();
  }));
}

function renderMetricCards(){
  const host=$('#mlCards'); if(!host) return;
  const li=byName('Lighter');
  const lcap=(li&&li.rev30&&li.fees30)?(li.rev30/li.fees30*100).toFixed(0)+'%':'—';
  const lhold=(li&&li.hold30&&li.rev30)?(li.hold30/li.rev30*100).toFixed(0)+'%':'—';
  const t=CARD_TEXT[ML_SEL]||{};
  host.innerHTML=mlPicked().map(v=>{
    const row=t[v.tag]||t._||['',''];
    const body=String(row[1]).replace('%LCAP%',lcap).replace('%LHOLD%',lhold);
    return `<div class="ml-card ${v.cls}"><span>${v.n} · ${row[0]}</span><b>${body}</b></div>`;
  }).join('');
}

function drawMetric(){
  const svg=$('#mlChart'); if(!svg) return;
  const m=METRICS.find(x=>x.k===ML_SEL);
  const buckets=windowBuckets(ML_RANGE);
  const W=760,H=300,pl=64,pr=14,pt=18,pb=52;
  const series=mlPicked().map(v=>({...v,d:mlSeries(v.n,m.k,ML_RANGE,buckets)}));
  const vals=series.flatMap(s=>s.d).filter(x=>x!=null);
  const max=Math.max(...vals,0)*1.12||1;
  const min=0;
  const n=buckets.length;
  const X=i=>pl+(i+0.5)/n*(W-pl-pr);
  const Y=v=>H-pb-(v-min)/(max-min||1)*(H-pt-pb);
  const bars=m.kind==='flow'&&n<=13;

  let g='';
  for(let t=0;t<=3;t++){
    const v=min+(max-min)*t/3, y=Y(v);
    g+=`<line class="grid" x1="${pl}" y1="${y.toFixed(1)}" x2="${W-pr}" y2="${y.toFixed(1)}"/>`
      +`<text class="ax" x="${pl-10}" y="${(y+4).toFixed(1)}" text-anchor="end">${m.fmt(v)}</text>`;
  }
  const fmtDay=iso=>new Date(iso+'T00:00:00Z').toLocaleDateString('en-US',{month:'short',day:'2-digit',timeZone:'UTC'});
  const every=Math.ceil(n/8);
  buckets.forEach((b,i)=>{
    if(i%every) return;
    if(b.days===1){
      g+=`<text class="ax wk" x="${X(i).toFixed(1)}" y="${H-pb+18}" text-anchor="middle">${fmtDay(b.end)}</text>`;
    }else{
      g+=`<text class="ax wk" x="${X(i).toFixed(1)}" y="${H-pb+18}" text-anchor="middle">${fmtDay(addDaysIso(b.end,-6))}</text>`
        +`<text class="ax wk dim" x="${X(i).toFixed(1)}" y="${H-pb+31}" text-anchor="middle">${fmtDay(b.end)}</text>`;
    }
  });

  if(bars){
    const slot=(W-pl-pr)/n, k=series.length, bw=Math.min(slot/(k+1.2),20);
    series.forEach((s,si)=>s.d.forEach((v,i)=>{
      if(v==null) return;
      const x=X(i)-(bw*k+2*(k-1))/2+si*(bw+2), y=Y(v);
      g+=`<rect class="bar ${s.cls}" x="${x.toFixed(1)}" y="${y.toFixed(1)}" width="${bw.toFixed(1)}"
        height="${Math.max(H-pb-y,1).toFixed(1)}" rx="2"><title>${s.n} ${m.fmt(v)}</title></rect>`;
    }));
  }else{
    series.forEach(s=>{
      const pts=s.d.map((v,i)=>v==null?null:[X(i),Y(v),v]).filter(Boolean);
      if(!pts.length) return;
      if(pts.length>1)
        g+=`<path class="ln ${s.cls}" d="${pts.map((p,i)=>(i?'L':'M')+p[0].toFixed(1)+' '+p[1].toFixed(1)).join(' ')}"/>`;
      if(n<=13) pts.forEach(p=>{ g+=`<circle class="dot ${s.cls}" cx="${p[0].toFixed(1)}" cy="${p[1].toFixed(1)}" r="3.2">`
        +`<title>${s.n} ${m.fmt(p[2])}</title></circle>`; });
    });
  }
  g+=`<line class="axis" x1="${pl}" y1="${H-pb}" x2="${W-pr}" y2="${H-pb}"/>`;
  svg.innerHTML=g;

  const legend=$('#mlLegend');
  if(legend) legend.innerHTML=series.map(s=>`<span class="${s.cls}"><i></i>${s.n}</span>`).join('');
  const span=ML_RANGE==='30D'?'30 daily periods'
    :ML_RANGE==='26W'?'26 complete 7-day periods'
    :ML_RANGE==='90D'?'13 complete 7-day periods':'8 complete 7-day periods';
  $('#mlTitle').textContent=m.label;
  $('#mlWindow').textContent=`${span} · ${addDaysIso(buckets[0].end,-(buckets[0].days-1))} to ${ANCHOR}`
    +` · anchored to the treasury series`;
  const gaps=series.filter(s=>!s.d.some(x=>x!=null)).map(s=>s.n);
  let denom='';
  if(m.k==='oiShare'||m.k==='volShare'){
    const key=m.k==='oiShare'?'oi':'vol';
    const n=VENUES.filter(v=>baseSeries(v.n,key,ML_RANGE,buckets).some(x=>x!=null)).length;
    denom=` · field = ${n} of ${VENUES.length} venues reporting`;
  }
  orNull('#mlRead').innerHTML=`<p>${m.note}</p><span class="ml-src">${m.src}${denom}`
    +`${gaps.length?` · no series for ${gaps.join(', ')}`:''}</span>`;
}

function renderMetricLab(){
  if(ML_SEL==='oiShare') ensureFieldOi();
  renderVenuePicker(); renderRangeButtons(); renderMetricList(); drawMetric(); renderMetricCards();
}

/* ---- daily series ---- */
const dayOf=ts=>new Date(Number(ts)*1000).toISOString().slice(0,10);
const chartToDaily=raw=>{
  const arr=Array.isArray(raw)?raw:(raw&&raw.totalDataChart)||[];
  const m={}; arr.forEach(([t,v])=>{ const d=dayOf(t); if(Number.isFinite(+v)) m[d]=+v; });
  return m;
};
const OI_FETCHED={};
/* open interest history is the one series refreshLlama does not already pull, so
   it is fetched only for venues actually on the chart */
async function ensureSeries(){
  const jobs=mlPicked().map(v=>byName(v.n)).filter(v=>v&&v.slug&&!OI_FETCHED[v.n]);
  if(!jobs.length) return;
  await Promise.all(jobs.map(async v=>{
    OI_FETCHED[v.n]=true;
    try{
      const raw=await fetch('https://api.llama.fi/v2/chart/open-interest/protocol/'+v.slug
        +'?dataType=openInterestAtEnd').then(r=>r.ok?r.json():null);
      const m=chartToDaily(raw);
      if(Object.keys(m).length) DAILY[v.n].oi=m;
    }catch(err){ /* the venue simply keeps whatever it had */ }
  }));
  renderMetricLab();
}
/* the share metrics divide by the whole field, so they need OI history for every
   venue — not just the ones on the chart. Fetched once, on demand. */
let FIELD_OI_DONE=false, FIELD_OI_READY=false;
async function ensureFieldOi(){
  if(FIELD_OI_DONE) return; FIELD_OI_DONE=true;
  const jobs=VENUES.filter(v=>v.slug&&!(DAILY[v.n]&&DAILY[v.n].oi));
  await Promise.all(jobs.map(async v=>{
    try{
      const raw=await fetch('https://api.llama.fi/v2/chart/open-interest/protocol/'+v.slug
        +'?dataType=openInterestAtEnd').then(r=>r.ok?r.json():null);
      const m=chartToDaily(raw);
      if(Object.keys(m).length) DAILY[v.n].oi=m;
    }catch(err){ /* that venue just stays out of the denominator */ }
  }));
  FIELD_OI_READY=true;
  renderMetricLab();
}
async function refreshWeekly(){ await ensureSeries(); await ensureFieldOi(); }

/* ==================================================================
   4. FEE -> REVENUE SPLIT
   ================================================================== */
function renderSplit(){
  const host=$('#splitList'); if(!host) return;
  const rows=VENUES.filter(v=>v.fees30>0).sort((a,b)=>b.fees30-a.fees30);
  host.innerHTML=rows.map(v=>{
    const c=capture(v);
    const w=c===null?0:Math.min(c,100);
    const inside=w>=82;   /* only when the fill leaves no room outside */
    const bar=c===null
      ? `<div class="sp-bar"><span class="natxt">revenue not published</span></div>`
      : `<div class="sp-bar"><span class="kept" style="width:${w.toFixed(1)}%"></span>`
        +`<span class="pctlbl ${inside?'inside':'outside'}" style="${inside?`left:${Math.max(w-13,2).toFixed(1)}%`:`left:calc(${w.toFixed(1)}% + 8px)`}">`
        +`${c.toFixed(0)}%${c>100?' !':''}</span></div>`;
    const val=c===null
      ? `<b>—</b><span>of ${usd(v.fees30)} pool</span>`
      : `<b>${usd(v.rev30)}</b><span>of ${usd(v.fees30)}${v.modeled?' *':''}</span>`;
    return `<div class="sp-row${v.me?' me':''}${v.ceiling?' ceil':''}">
      <div class="sp-name"><img src="${v.logo}" alt="" width="18" height="18"><b>${esc(v.n)}</b></div>
      ${bar}
      <div class="sp-val">${val}</div>
    </div>`;
  }).join('');

  const va=byName('Variational'), li=byName('Lighter'), hl=byName('Hyperliquid');
  const others=rows.filter(v=>!v.me&&capture(v)!==null&&capture(v)<=100).map(capture);
  const med=median(others);
  orNull('#splitCallout').innerHTML=`<b>Same pool, different policy</b>
    <p>Variational books <b>${capture(va).toFixed(0)}%</b> of its trader fee pool into the treasury;
    Lighter books ${capture(li).toFixed(0)}%, Hyperliquid ${capture(hl).toFixed(0)}%, and the field median is
    ${med.toFixed(0)}%. The other ${(100-capture(va)).toFixed(0)}% is not lost — it funds OLP returns and
    market-making cost, which is what makes a ${usd(va.fees30)} pool at ${bps(takeRate(va))} bps possible
    in the first place. Comparing treasury dollars across venues therefore compares payout policies, not
    trading businesses. Variational's own split is the reported policy ratio (†), not an independently
    measured one — the fee pool is derived from it.</p>`;
}

/* ==================================================================
   5. FEE FLOW  — DeFiLlama's income-statement shape, per venue
        trader fees -> cost of revenue | gross profit -> token holders
   ================================================================== */
const FLOW_SET=['Variational','Lighter','Extended','Hyperliquid'];

function ribbon(x1,y1,x2,y2,h1,h2){
  const cx=(x1+x2)/2;
  return `M${x1} ${y1} C${cx} ${y1} ${cx} ${y2} ${x2} ${y2}`
    +` L${x2} ${y2+h2} C${cx} ${y2+h2} ${cx} ${y1+h1} ${x1} ${y1+h1} Z`;
}

function flowCard(v){
  const W=440,H=230,top=52,bot=14,nw=13,gap=13;
  const usable=H-top-bot;
  const fees=v.fees30, rev=v.rev30, hold=v.hold30;
  const x0=6, x1=Math.round(W*0.45), x2=W-nw-6;
  const S=n=>n/fees*usable;
  const cls=v.me?'me':v.ceiling?'ceil':'peer';
  const chip=(k,label,val)=>val>0
    ? `<span class="fc-chip ${k}"><i></i>${label} <b>${usd(val)}</b> · ${(val/fees*100).toFixed(0)}%</span>`
    : '';

  if(!(rev>0)){
    return `<figure class="flow-card ${cls}">
      <figcaption><img src="${v.logo}" alt="" width="18" height="18"><b>${esc(v.n)}</b>
        <span>${usd(fees)} trader fees · 30D</span></figcaption>
      <svg viewBox="0 0 ${W} ${H}" role="img" aria-label="${esc(v.n)} fee flow, split not published">
        <rect class="node fees" x="${x0}" y="${top}" width="${nw}" height="${usable}" rx="3"/>
        <text class="nl" x="${x0}" y="${top-28}">Trader fees</text>
        <text class="nv" x="${x0}" y="${top-11}">${usd(fees)}</text>
        <text class="na" x="${x0+nw+16}" y="${top+usable/2}">no revenue split published on DeFiLlama</text>
      </svg>
      <div class="fc-chips"><span class="fc-chip na"><i></i>cost of revenue not broken out</span></div>
      </figure>`;
  }

  /* cost of revenue, split as far as the free endpoints go:
     the LP/vault share is published, the rest is rebates and builder-style distributions */
  const cost=Math.max(fees-rev,0);
  const supply=Number.isFinite(v.sup30)&&v.sup30>0?Math.min(v.sup30,cost):(v.me?cost:0);
  const other=Math.max(cost-supply,0);
  const segs=[
    {k:'rev',   v:rev,    y:0},
    {k:'supply',v:supply, y:0},
    {k:'other', v:other,  y:0}
  ].filter(d=>d.v>0);

  /* left bar segments run in the same order as the right-hand nodes, so ribbons never cross */
  let acc=top;
  segs.forEach(d=>{ d.sy=acc; d.h=S(d.v); acc+=d.h; });
  let ny=top;
  segs.forEach(d=>{ d.ny=ny; ny+=d.h+gap; });

  const revSeg=segs.find(d=>d.k==='rev');
  const holdOk=Number.isFinite(hold)&&hold>0;
  const hHold=holdOk?S(Math.min(hold,rev)):0;
  const hKeep=holdOk?Math.max(revSeg.h-hHold,0):0;

  return `<figure class="flow-card ${cls}">
    <figcaption><img src="${v.logo}" alt="" width="18" height="18"><b>${esc(v.n)}</b>
      <span>${usd(fees)} trader fees · 30D${v.modeled?' · modeled *':''}</span></figcaption>
    <svg viewBox="0 0 ${W} ${H}" role="img"
         aria-label="${esc(v.n)}: ${usd(fees)} of trader fees splits into ${usd(rev)} booked and ${usd(cost)} paid out">
      ${segs.map(d=>`<path class="rib ${d.k}" d="${ribbon(x0+nw,d.sy,x1,d.ny,d.h,d.h)}"/>`).join('')}
      ${holdOk?`<path class="rib hold" d="${ribbon(x1+nw,revSeg.ny,x2,revSeg.ny,hHold,hHold)}"/>`:''}
      ${holdOk&&hKeep>2?`<path class="rib keep2" d="${ribbon(x1+nw,revSeg.ny+hHold,x2,revSeg.ny+hHold,hKeep,hKeep)}"/>`:''}
      <rect class="node fees" x="${x0}" y="${top}" width="${nw}" height="${usable}" rx="3"/>
      ${segs.map(d=>`<rect class="node ${d.k}" x="${x1}" y="${d.ny.toFixed(1)}" width="${nw}" height="${Math.max(d.h,2).toFixed(1)}" rx="3"/>`).join('')}
      ${holdOk?`<rect class="node hold" x="${x2}" y="${revSeg.ny.toFixed(1)}" width="${nw}" height="${Math.max(hHold,2).toFixed(1)}" rx="3"/>`:''}
      <text class="nl" x="${x0}" y="${top-28}">Trader fees</text>
      <text class="nv" x="${x0}" y="${top-11}">${usd(fees)}</text>
      <text class="nl" x="${x1}" y="${top-28}">${v.me?'Treasury':'Booked revenue'}</text>
      <text class="nv" x="${x1}" y="${top-11}">${usd(rev)} · ${(rev/fees*100).toFixed(0)}%</text>
      ${holdOk
        ? `<text class="nl" x="${x2+nw}" y="${top-28}" text-anchor="end">To holders</text>
           <text class="nv" x="${x2+nw}" y="${top-11}" text-anchor="end">${usd(hold)} · ${(hold/fees*100).toFixed(0)}%</text>`
        : `<text class="na" x="${x2+nw}" y="${revSeg.ny+Math.max(revSeg.h/2,10)}" text-anchor="end">no onward split</text>`}
    </svg>
    <div class="fc-chips">
      ${chip('supply', v.me?'OLP + market making':'LP / vault suppliers', supply)}
      ${chip('other',  v.me?'other payouts':'rebates + builder payouts', other)}
      ${holdOk&&hKeep>2?chip('keep2','retained by protocol',rev-hold):''}
    </div>
  </figure>`;
}

function renderFlow(){
  const host=$('#flowGrid'); if(!host) return;
  host.innerHTML=FLOW_SET.map(byName).filter(Boolean).filter(v=>v.fees30>0).map(flowCard).join('');
  const va=byName('Variational'), hl=byName('Hyperliquid'), li=byName('Lighter');
  orNull('#flowNote').innerHTML=`The shape follows DeFiLlama's income statement: gross protocol revenue (what traders
    pay) less cost of revenue (maker rebates, builder codes, LP and market-making share) leaves gross profit,
    and what leaves that for the token is holders' revenue. Hyperliquid runs the whole
    ${usd(hl.rev30)} of its gross profit into buybacks; Lighter books ${usd(li.rev30)} and sends
    ${usd(li.hold30)} of it to holders. Variational's first split is the reported
    ${(VAR_SPREAD_SHARE*100).toFixed(0)}/${(100-VAR_SPREAD_SHARE*100).toFixed(0)} policy applied to a modeled
    pool (*), and it publishes no onward distribution series, so the third column stays empty rather than
    being filled with the dashboard's own burn assumption.`;
}

/* One provenance line, generated from the state the page is actually in — live or
   snapshot, CoinGecko or DeFiLlama — rather than a sentence typed once and left to
   go stale. The integration overrides OI_LABEL when the dashboard swaps the source. */
let OI_LABEL=null;
function provenance(){
  const oi=OI_LABEL||(STATE.cgLive?'CoinGecko derivatives (live)':'CoinGecko snapshot '+SNAP_AS_OF);
  const vol=STATE.cgLive?'CoinGecko derivatives (live)':'CoinGecko snapshot '+SNAP_AS_OF;
  const fees=STATE.llamaLive?'DeFiLlama (live)':'DeFiLlama snapshot '+SNAP_AS_OF;
  return (OI_MIXED?`⚠ ${OI_MIXED_NOTE} — open-interest shares are withheld while that is true. `:'')
    +`Open interest ${oi} · 24H volume ${vol} · peer fees, revenue and holder payouts ${fees}`
    +(OI_STALE_NOTE?` · ${OI_STALE_NOTE}`:'')
    +` · Variational fee pool modeled: Arbitrum treasury inflow ÷ the reported `
    +`${(VAR_SPREAD_SHARE*100).toFixed(0)}% allocation — an estimate, not booked revenue`;
}
function renderProvenance(){
  document.querySelectorAll('[data-src-line]').forEach(el=>{
    el.textContent=provenance();
    el.classList.toggle('warn',OI_MIXED);
  });
}

function renderFieldModes(){
  const host=$('#fieldModes'); if(!host) return;
  const modes=[['activity','Activity'],['valuation','Valuation']];
  host.innerHTML=modes.map(([k,label])=>
    `<button type="button" class="rg${k===FIELD_MODE?' on':''}" data-fmode="${k}">${label}</button>`).join('');
  host.querySelectorAll('.rg').forEach(b=>b.addEventListener('click',()=>{
    FIELD_MODE=b.dataset.fmode;
    renderFieldModes(); renderField();
    if(FIELD_MODE==='valuation') refreshMarketCaps();
  }));
}

/* live circulating market caps for the valuation plane (same free endpoint the
   dashboard uses; skipped entirely while the chart is in activity mode) */
let MCAP_DONE=false;
async function refreshMarketCaps(){
  if(MCAP_DONE) return; MCAP_DONE=true;
  try{
    const ids=CL_VAL_COMPS.map(c=>c.cg).join(',');
    const res=await fetch('https://api.coingecko.com/api/v3/coins/markets?vs_currency=usd&ids='
      +encodeURIComponent(ids)+'&sparkline=false');
    if(!res.ok) throw new Error('mcap http '+res.status);
    const live=await res.json();
    if(!Array.isArray(live)) throw new Error('bad payload');
    live.forEach(row=>{
      const c=CL_VAL_COMPS.find(x=>x.cg===row.id);
      if(c&&row.market_cap>0) c.mc=row.market_cap;
    });
  }catch(err){ console.warn('Market-cap sync kept the snapshot:', err); }
  /* open interest for the comps comes from the board we already refresh */
  CL_VAL_COMPS.forEach(c=>{ const v=byName(c.n); if(v&&v.oi>0) c.oi=v.oi; });
  if(FIELD_MODE==='valuation') renderField();
}

function renderAll(){ renderProvenance(); renderFieldModes(); renderField(); renderRatios(); renderMetricLab(); renderSplit(); renderFlow(); stamp(); }


